import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Frensense v2: the first preview","description":"Why we rebuilt the engine as a compiler, and what 0.7.1-preview.1 ships, memory-safety checkers, value-aware guards, and a corpus that teaches the engine.","frontmatter":{"title":"Frensense v2: the first preview","date":"2026-09-28T00:00:00.000Z","description":"Why we rebuilt the engine as a compiler, and what 0.7.1-preview.1 ships, memory-safety checkers, value-aware guards, and a corpus that teaches the engine."},"headers":[],"relativePath":"blog/2026-09-28-v2-preview.md","filePath":"blog/2026-09-28-v2-preview.md"}'),s={name:"blog/2026-09-28-v2-preview.md"};function i(o,e,h,l,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="frensense-v2-the-first-preview" tabindex="-1">Frensense v2: the first preview <a class="header-anchor" href="#frensense-v2-the-first-preview" aria-label="Permalink to &quot;Frensense v2: the first preview&quot;">​</a></h1><p>v1 taught us an important lesson: pattern-shaped detection plateaus quickly. Every new framework needed another rule, every rule brought false positives, and the rules could not reason about <em>how</em> data moves.</p><p>So v2 is a <strong>compiler first, checker second</strong>. Every file is lowered to a lightweight IR; the engine builds def-use chains, a call graph, Steensgaard points-to, a heap model with memory SSA, and an SVFG. A finding is an exact reachability query on that graph, with the concrete source-to-sink path attached.</p><h2 id="what-s-in-0-7-1-preview-1" tabindex="-1">What&#39;s in 0.7.1-preview.1 <a class="header-anchor" href="#what-s-in-0-7-1-preview-1" aria-label="Permalink to &quot;What&#39;s in 0.7.1-preview.1&quot;">​</a></h2><ul><li><strong>Memory safety</strong>: use-after-free, double-free (with interprocedural allocation/deallocation wrapper summaries), and out-of-bounds checkers.</li><li><strong>Value-aware guards</strong>: an abstract-interpretation value lattice with branch sharpening, inside <code>if i &lt; arr.len()</code>, the engine <em>knows</em> the bound holds, so range guards are proven, not pattern-matched.</li><li><strong>A corpus that teaches</strong>: label a vulnerable example and its fixed twin, and the bundler learns source/sink/sanitizer facts <em>and</em> policies into a checksummed <code>.frc</code> bundle. Facts must replay-verify before they ship.</li><li><strong>Agent surface</strong>: MCP (audit, scan-file, diff), LSP diagnostics, GitHub Actions annotations, and stable finding IDs.</li></ul><h2 id="where-v1-went" tabindex="-1">Where v1 went <a class="header-anchor" href="#where-v1-went" aria-label="Permalink to &quot;Where v1 went&quot;">​</a></h2><p>The v1 documentation is preserved at <a href="/v1/">/v1/</a>. We kept it online on purpose: it documents what the first attempt could and could not do, and the <a href="https://github.com/Friehub/Frensense" target="_blank" rel="noreferrer">gap analysis</a> that motivated the rebuild. v2&#39;s architecture chapters are the answer to those gaps.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>The corpus is the roadmap now. Next milestones: a relational/octagon value domain (B2), heap model v2 for prototype-pollution flows, and per-framework <code>.frc</code> bundles starting with Next.js.</p>',9)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
